<?php get_header(); if (have_posts()) : while (have_posts()) : the_post(); ?>
<article <?php post_class('alify-single-content'); ?>><?php if (!alify_sections_contains_hero(get_the_ID())) : ?><section class="alify-section alify-testimonial-single"><div class="container"><p class="alify-eyebrow"><?php esc_html_e('Client story','alify'); ?></p><h1><?php the_title(); ?></h1><figure class="alify-quote"><blockquote><?php echo esc_html(get_field('quote')); ?></blockquote><figcaption><strong><?php echo esc_html(get_field('client_name')); ?></strong> <?php echo esc_html(get_field('client_role')); ?></figcaption></figure><?php if (has_post_thumbnail()) { the_post_thumbnail('medium',array('loading'=>'lazy')); } ?></div></section><?php endif; ?><?php alify_render_post_content(get_the_ID()); ?></article>
<?php endwhile; endif; get_footer(); ?>
